                    $ConditionValue = [string]$ConditionNode.InnerText

                    $FilterInventory += [PSCustomObject]@{
                        event_id = $EventId
                        event_type = $EventType
                        onmatch = $OnMatch
                        field = $ConditionName
                        condition = $ConditionType
                        value = $ConditionValue
                    }

