        $EventTypes = @(
            Get-EventTypesForId `
                -EventId $EventId
        )

        foreach ($EventType in $EventTypes) {

            $Nodes = @(
                $EventFiltering.SelectNodes(
                    ".//*[local-name()='$EventType']"
                )
            )

            foreach ($Node in $Nodes) {

                $OnMatch = [string]$Node.GetAttribute(
                    "onmatch"
