                if ([string]::IsNullOrWhiteSpace($OnMatch)) {
                    $OnMatch = "not_specified"
                }

                # -----------------------------------------------------------
                # Record all include/exclude filters for evidence.
                # -----------------------------------------------------------

                $Conditions = @(
                    $Node.SelectNodes(
                        ".//*[not(*)]"
                    )
                )

                if ($Conditions.Count -eq 0) {

                    $FilterInventory += [PSCustomObject]@{
                        event_id = $EventId
                        event_type = $EventType
                        onmatch = $OnMatch
                        field = $null
                        condition = $null
                        value = $null
                    }
                }

